import{_ as e,o,c as a,a2 as l}from"./chunks/framework.ClgMjOt7.js";const p=JSON.parse('{"title":"ブックマーク & フォロー管理","description":"公開/非公開ブックマーク、ブックマークタグ、フォロー中フィード、自動連動仕様","frontmatter":{"title":"ブックマーク & フォロー管理","description":"公開/非公開ブックマーク、ブックマークタグ、フォロー中フィード、自動連動仕様"},"headers":[],"relativePath":"features/bookmarks-following.md","filePath":"features/bookmarks-following.md","lastUpdated":1786169627000}'),r={name:"features/bookmarks-following.md"};function d(i,t,s,n,c,f){return o(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="ブックマーク-フォロー管理" tabindex="-1">ブックマーク &amp; フォロー管理 <a class="header-anchor" href="#ブックマーク-フォロー管理" aria-label="Permalink to &quot;ブックマーク &amp; フォロー管理&quot;">​</a></h1><p>気になった作品の保存および好みの作者の追跡を行う管理機能の仕様です。</p><hr><h2 id="ブックマーク機能-bookmarkscreen" tabindex="-1">ブックマーク機能 (<code>BookmarkScreen</code>) <a class="header-anchor" href="#ブックマーク機能-bookmarkscreen" aria-label="Permalink to &quot;ブックマーク機能 (`BookmarkScreen`)&quot;">​</a></h2><p>作品詳細画面および各種一覧のブックマークアイコンから操作可能です。</p><h3 id="_1-公開範囲-restrict" tabindex="-1">1. 公開範囲 (<code>Restrict</code>) <a class="header-anchor" href="#_1-公開範囲-restrict" aria-label="Permalink to &quot;1. 公開範囲 (`Restrict`)&quot;">​</a></h3><ul><li><code>Restrict.Public</code>: プロフィール上に公開されるブックマーク。</li><li><code>Restrict.Private</code>: 自分のみが参照可能な非公開ブックマーク。</li></ul><div class="tip custom-block"><p class="custom-block-title">クイック切替ショートカット</p><p>ブックマークボタンを長押しすることで、公開範囲および付与するブックマークタグを直接指定できる設定ダイアログが起動します。</p></div><h3 id="_2-ブックマーク用タグ" tabindex="-1">2. ブックマーク用タグ <a class="header-anchor" href="#_2-ブックマーク用タグ" aria-label="Permalink to &quot;2. ブックマーク用タグ&quot;">​</a></h3><p>Pixiv のブックマーク分類タグに対応しています。</p><ul><li>ブックマーク追加時、作品に登録されているメインタグから選択またはカスタムタグを手動入力。</li><li>ブックマーク一覧画面において、設定されたタグでフィルタリング閲覧が可能。</li></ul><hr><h2 id="フォロー管理-userprofilescreen" tabindex="-1">フォロー管理 (<code>UserProfileScreen</code>) <a class="header-anchor" href="#フォロー管理-userprofilescreen" aria-label="Permalink to &quot;フォロー管理 (`UserProfileScreen`)&quot;">​</a></h2><ul><li><strong>公開フォロー (<code>Restrict.Public</code>)</strong>: 作者にフォローが通知され、自身のフォロー中一覧に公開表示。</li><li><strong>非公開フォロー (<code>Restrict.Private</code>)</strong>: 作者に通知されず、非公開で更新を追跡。</li><li><strong>フォロー中タイムライン</strong>: ホーム画面の「フォロー中」タブから、フォローしている全クリエイターの新着投稿をタイムライン形式で一括閲覧。</li></ul><hr><h2 id="自動アクション連動フラグ-appsettings" tabindex="-1">自動アクション連動フラグ (<code>AppSettings</code>) <a class="header-anchor" href="#自動アクション連動フラグ-appsettings" aria-label="Permalink to &quot;自動アクション連動フラグ (`AppSettings`)&quot;">​</a></h2><p>設定画面で有効化できる連携機能のフラグ一覧です。</p><table tabindex="0"><thead><tr><th style="text-align:left;">フラグ名</th><th style="text-align:left;">型</th><th style="text-align:left;">説明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>autoDownloadOnBookmark</code></td><td style="text-align:left;"><code>Boolean</code></td><td style="text-align:left;">作品をブックマークに追加した際、同時にバックグラウンドでローカルストレージへ保存</td></tr><tr><td style="text-align:left;"><code>autoBookmarkOnDownload</code></td><td style="text-align:left;"><code>Boolean</code></td><td style="text-align:left;">作品をローカルへダウンロード保存した際、同時に Pixiv 上のブックマークにも追加</td></tr><tr><td style="text-align:left;"><code>autoTagOnBookmark</code></td><td style="text-align:left;"><code>Boolean</code></td><td style="text-align:left;">ブックマーク追加時、作品のトップタグを自動的にブックマークタグとして設定</td></tr><tr><td style="text-align:left;"><code>followOnLike</code></td><td style="text-align:left;"><code>Boolean</code></td><td style="text-align:left;">作品を「いいね！」した際、作者を自動的にフォロー</td></tr><tr><td style="text-align:left;"><code>privateBookmarkDefault</code></td><td style="text-align:left;"><code>Boolean</code></td><td style="text-align:left;">ブックマーク追加時の初期選択状態を「非公開」に固定</td></tr></tbody></table>',18)])])}const u=e(r,[["render",d]]);export{p as __pageData,u as default};
